<?php
namespace Modules\StockTransferNew\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\StockTransferNew\Entities\StockTransfer;use Modules\StockTransferNew\Services\StockTransferApprovalWorkflowService;use Modules\StockTransferNew\Utilities\StockTransferTenant;
class ApprovalWorkflowController extends Controller{public function __construct(protected StockTransferApprovalWorkflowService $approval){}public function index(){$transfers=StockTransfer::with('approvalSteps')->where('business_id',StockTransferTenant::businessId())->whereIn('status',['pending_approval','returned_for_correction','rejected'])->latest()->paginate(25);return view('stocktransfernew::approvals.workflow',compact('transfers'));}public function approve(Request $request,StockTransfer $transfer){$this->approval->approveStep($transfer,$request->input('remarks'));return back()->with('status','Approval step completed.');}public function reject(Request $request,StockTransfer $transfer){$this->approval->reject($transfer,$request->input('remarks'));return back()->with('status','Transfer rejected.');}public function return(Request $request,StockTransfer $transfer){$this->approval->returnForCorrection($transfer,$request->input('remarks'));return back()->with('status','Transfer returned for correction.');}}
